import jetbrains.buildServer.configs.kotlin.*
import jetbrains.buildServer.configs.kotlin.buildFeatures.XmlReport
import jetbrains.buildServer.configs.kotlin.buildFeatures.xmlReport
import jetbrains.buildServer.configs.kotlin.buildSteps.powerShell
import jetbrains.buildServer.configs.kotlin.buildSteps.script
import jetbrains.buildServer.configs.kotlin.triggers.vcs
import jetbrains.buildServer.configs.kotlin.vcs.GitVcsRoot
import java.io.File

/*
 * apache/maven → TeamCity, generated by the TeamCity migration factory.
 * Design, parity checklist and sizing evidence: work/design/apache__maven.md.
 * Source of truth for the matrix: upstream .github/workflows/maven.yml ("Java CI").
 */

version = "2026.03"

// GitHub App connection PROJECT_EXT_66 ("TeamCity - demo.teamcity.com", at _Root).
// The token id exists only once the App is installed on arokhin/maven and the
// connection is authorized (approval checkpoint). It is a reference, not a secret.
// Until then, the VCS root clones the public fork anonymously (read-only).
val githubAppTokenId = ""

val SourcesVcs = GitVcsRoot({
    id("Sources")
    name = "arokhin/maven (fast-forward mirror of apache/maven)"
    url = "https://github.com/arokhin/maven.git"
    branch = "refs/heads/master"
    branchSpec = "+:refs/heads/master"
    if (githubAppTokenId.isNotEmpty()) {
        authMethod = token {
            userName = "oauth2"
            tokenId = githubAppTokenId
        }
    } else {
        authMethod = anonymous()
    }
})

enum class Os(val family: String, val idPart: String, val title: String) {
    LINUX("Linux", "Linux", "Linux"),
    WINDOWS("Windows", "Windows", "Windows"),
    MACOS("Mac OS", "MacOs", "macOS"),
}

enum class Kind(val idPart: String, val title: String, val script: String, val timeoutMin: Int) {
    // Timeouts: observed GHA durations (brief) were initial ~7 min, full-build 6–17 min,
    // ITs 13–36 min. Each build starts with a cold per-build local repo (no cache,
    // Lesson 7), so allow roughly 3x the worst observed time.
    FULL("FullBuild", "Full build", "full-build.sh", 90),
    ITS("IntegrationTests", "Integration tests", "integration-tests.sh", 120),
}

fun readScript(name: String) = File(DslContext.baseDir, "scripts/$name").readText()

// Single-quoted here-string: PowerShell expands nothing inside, so the bash body
// passes through verbatim. CRs are stripped because bash rejects CRLF scripts.
fun psWrap(body: String) = listOf(
    "\$ErrorActionPreference = 'Stop'",
    "\$body = @'",
    body,
    "'@",
    "\$path = Join-Path (Get-Location).Path 'mf-step.sh'",
    "[IO.File]::WriteAllText(\$path, (\$body -replace \"`r\", ''))",
    "& 'C:\\Program Files\\Git\\bin\\bash.exe' -eo pipefail \$path",
    "exit \$LASTEXITCODE",
).joinToString("\n")

// Every step is a raw bash script, not the Maven runner. The runner can rewrite or
// drop arguments (Lesson 3), and the source CI's exact mvn command lines are what
// we mirror. On Windows the same bash runs under Git Bash (agent env.Path has
// C:\Program Files\Git\bin, per the capability probe), started from PowerShell,
// because the Command Line runner there only speaks cmd.
fun BuildSteps.bashStep(stepName: String, os: Os, vararg parts: String) {
    val body = (listOf("common.sh") + parts).joinToString("\n") { readScript(it) }
    if (os == Os.WINDOWS) {
        powerShell {
            name = stepName
            scriptMode = script { content = psWrap(body) }
        }
    } else {
        script {
            name = stepName
            scriptContent = "#!/usr/bin/env bash\nset -eo pipefail\n$body"
        }
    }
}

// Tier selection (Lesson 11). The Default pool is discrete EC2 bundles: Small=2,
// Medium=4, Large=8 CPUs (Windows: Large only). cpuCount alone picks the tier, so
// no memory requirement is set: it would be inert documentation, not a lever.
fun Requirements.tier(os: Os, cpus: Int?) {
    equals("teamcity.agent.jvm.os.family", os.family)
    if (cpus != null) equals("teamcity.agent.hardware.cpuCount", cpus.toString())
}

// Pass-1 sizing (rough cut, refined in phase 6 from TeamCity's built-in
// per-build CPU/memory statistics). Evidence: GHA hosted runners are 4 vCPU / 16 GB.
fun cpusFor(kind: Kind?, os: Os): Int? = when (os) {
    // Windows has only the Large tier (c5d.2xlarge, 8 CPU / 15.9 GB).
    Os.WINDOWS -> 8
    // No macOS agents in the Default pool; the only macOS agents on the server
    // belong to another team's "Self-hosted for Unity" pool, and are disconnected.
    Os.MACOS -> null
    Os.LINUX -> when (kind) {
        // ITs fork a Maven JVM per test project, so they are memory-hungry. Medium
        // (7.6 GB) is half the GHA runner's RAM; Large (15.2 GB) matches it. ITs are
        // also the critical path toward the ~56 min SLA.
        Kind.ITS -> 8
        // Compile/test-bound reactor build. Medium matches GHA's 4 vCPU.
        else -> 4
    }
}

val heapDumpOpts = "-XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=./target/java_heapdump.hprof"

val InitialBuild = BuildType({
    id("InitialBuild")
    name = "Initial build (Linux · JDK 17)"
    description = "GHA job initial-build: bootstrap the wrapper (Maven 4.0.0-rc-7), ./mvnw verify, publish the Maven distribution."

    vcs {
        root(SourcesVcs)
        cleanCheckout = true
    }
    params {
        param("env.JAVA_HOME", "%env.JDK_17_0%")
        param("env.MF_OS", "Linux")
        param("env.MF_WRAPPER_MAVEN", "4.0.0-rc-7")
        param("env.MAVEN_OPTS", heapDumpOpts)
    }
    steps {
        bashStep("Wrapper + verify", Os.LINUX, "initial-build.sh")
    }
    requirements { tier(Os.LINUX, cpusFor(null, Os.LINUX)) }
    artifactRules = """
        apache-maven/target/apache-maven*.zip => maven-dist
        apache-maven/target/apache-maven*.tar.gz => maven-dist
        **/target/surefire-reports/** => reports/surefire.zip
        **/target/java_heapdump.hprof => reports/heapdumps.zip
    """.trimIndent()
    publishArtifacts = PublishMode.ALWAYS
    failureConditions { executionTimeoutMin = 60 }
    features {
        xmlReport {
            reportType = XmlReport.XmlReportType.JUNIT
            rules = "+:**/target/surefire-reports/TEST-*.xml"
        }
    }
})

data class Cell(val kind: Kind, val os: Os, val jdk: Int) {
    // Live: Linux + Windows × JDK 17/25. Paused-and-documented (Lesson 17):
    //  - every macOS cell: no macOS agent is available to this project;
    //  - every JDK 27 cell: JDK 27 is pre-GA, and no agent has env.JDK_27_0 (probe).
    val pauseReason: String? = when {
        os == Os.MACOS -> "no macOS agents in the Default pool on demo.teamcity.com"
        jdk == 27 -> "JDK 27 is pre-GA and not installed on any agent (no env.JDK_27_0)"
        else -> null
    }
    val live get() = pauseReason == null
}

fun cellBuildType(cell: Cell): BuildType = BuildType({
    val (kind, os, jdk) = cell
    id("${kind.idPart}_${os.idPart}_Jdk$jdk")
    name = "${kind.title} · ${os.title} · JDK $jdk"
    description = "GHA job ${if (kind == Kind.FULL) "full-build" else "integration-tests"} [os=${os.title}, java=$jdk]" +
        (cell.pauseReason?.let { " · PAUSED: $it" } ?: "")
    paused = !cell.live

    vcs {
        root(SourcesVcs)
        cleanCheckout = true
    }
    params {
        // Must be spelled exactly as the agents report it (env.JDK_17_0 / env.JDK_25_0,
        // per the probe). A typo here is an implicit requirement that makes every
        // agent incompatible without any runtime error (Lesson 4).
        param("env.JAVA_HOME", "%env.JDK_${jdk}_0%")
        param("env.MF_OS", os.family)
        param("env.MF_SITE", (kind == Kind.FULL && os == Os.LINUX).toString())
        param("env.MIMIR_VERSION", "0.13.0")
        param("env.MAVEN_OPTS", heapDumpOpts)
    }
    steps {
        bashStep("${kind.title} with the just-built Maven", os, "use-dist.sh", kind.script)
    }
    requirements { tier(os, cpusFor(kind, os)) }
    dependencies {
        // Lesson 6: the same revision (snapshot) AND the distribution file (artifact).
        // Either one alone under-delivers. Lesson 7: the distribution arrives as an
        // artifact, never via shared agent disk.
        dependency(InitialBuild) {
            snapshot {
                onDependencyFailure = FailureAction.FAIL_TO_START
                onDependencyCancel = FailureAction.CANCEL
            }
            artifacts {
                artifactRules = "maven-dist/** => maven-dist"
            }
        }
    }
    artifactRules = """
        **/target/surefire-reports/** => reports/surefire.zip
        **/target/failsafe-reports/** => reports/failsafe.zip
        **/target/java_heapdump.hprof => reports/heapdumps.zip
    """.trimIndent()
    publishArtifacts = PublishMode.ALWAYS
    failureConditions { executionTimeoutMin = kind.timeoutMin }
    features {
        xmlReport {
            reportType = XmlReport.XmlReportType.JUNIT
            rules = """
                +:**/target/surefire-reports/TEST-*.xml
                +:**/target/failsafe-reports/TEST-*.xml
            """.trimIndent()
        }
    }
})

val cells = Kind.values().flatMap { kind ->
    listOf(Os.LINUX, Os.MACOS, Os.WINDOWS).flatMap { os -> listOf(17, 25, 27).map { Cell(kind, os, it) } }
}
val cellTypes = cells.associateWith { cellBuildType(it) }

fun placeholder(idPart: String, title: String, source: String, reason: String): BuildType = BuildType {
    id("Side_$idPart")
    name = title
    description = "$source · PAUSED: $reason"
    paused = true
    params { param("env.MF_PLACEHOLDER_REASON", reason) }
    steps { bashStep("Not migrated", Os.LINUX, "paused-placeholder.sh") }
    requirements { tier(Os.LINUX, 2) }
}

val SnapshotDeploy = BuildType({
    id("Side_SnapshotDeploy")
    name = "Snapshot deploy (ASF Jenkinsfile)"
    description = "ASF Jenkinsfile deploy on master/maven-4.0.x/maven-3.9.x · PAUSED: needs ASF Nexus deploy rights this factory does not have."
    paused = true

    vcs {
        root(SourcesVcs)
        cleanCheckout = true
    }
    params {
        param("env.JAVA_HOME", "%env.JDK_17_0%")
        param("env.MF_OS", "Linux")
        // Jenkinsfile: MAVEN_OPTS=-Xms4G -Xmx4G. Medium's 7.6 GB fits a 4 GB heap.
        param("env.MAVEN_OPTS", "-Xms4G -Xmx4G -Djava.awt.headless=true")
        // Secrets by reference only (Lesson 9). Before un-pausing, store each value with
        // `teamcity project token put` and set the param to the credentialsJSON:<id>
        // reference it returns. Never put a literal value here.
        password("env.MF_ASF_NEXUS_USER", "", label = "ASF Nexus deploy user (credentialsJSON ref)")
        password("env.MF_ASF_NEXUS_PASSWORD", "", label = "ASF Nexus deploy password (credentialsJSON ref)")
    }
    steps { bashStep("Deploy snapshots", Os.LINUX, "snapshot-deploy.sh") }
    requirements { tier(Os.LINUX, 4) }
})

val sideWorkflows = listOf(
    placeholder("ConsolidateCaches", "Consolidate Mimir caches (maven.yml)", "GHA maven.yml job consolidate-caches [3 OS]",
        "publishes the GitHub Actions cache; TeamCity builds are stateless, so there is no equivalent"),
    placeholder("ReleaseDrafter", "Release Drafter", "GHA release-drafter.yml",
        "drafts GitHub Releases through the GitHub API, which needs a write token"),
    placeholder("UpdateLifecyclePlugins", "Update lifecycle plugin versions", "GHA update-lifecycle-plugins.yml",
        "opens upstream PRs through the GitHub API, which needs a write token"),
    placeholder("StaleBranchesReport", "Stale branches report", "GHA stale-branches.yml",
        "a GitHub repo-housekeeping report"),
    placeholder("Stale", "Stale issues and PRs", "GHA stale.yml", "a GitHub issue/PR bot"),
    placeholder("PrAutomation", "PR automation", "GHA pr-automation.yml", "a GitHub PR bot"),
    placeholder("PrCheck", "PR check", "GHA pr-check.yml", "a GitHub PR bot (runs on workflow_run)"),
    placeholder("PrSignal", "PR signal", "GHA pr-signal.yml", "a GitHub PR bot"),
)

val All = BuildType({
    id("All")
    name = "All (Java CI matrix)"
    type = BuildTypeSettings.Type.COMPOSITE
    description = "Whole GHA maven.yml chain. It depends only on the live cells: a snapshot dependency on a paused cell " +
        "(macOS ×6, JDK 27 ×4) would pull an unrunnable build into the chain and leave it waiting forever."

    vcs { root(SourcesVcs) }
    triggers {
        vcs { branchFilter = "+:<default>" }
    }
    dependencies {
        snapshot(InitialBuild) { onDependencyFailure = FailureAction.ADD_PROBLEM }
        cellTypes.filterKeys { it.live }.values.forEach {
            snapshot(it) { onDependencyFailure = FailureAction.ADD_PROBLEM }
        }
    }
})

// Relative-id hierarchy: this project's id (TcMf_ApacheMaven) and name
// ("apache/maven (migration factory)") are set when the server project is created at the
// approval checkpoint, and every id() below is automatically prefixed with that id.
project {
    description = "Generated by the TeamCity migration factory from apache/maven .github/workflows/maven.yml"

    vcsRoot(SourcesVcs)
    buildType(All)
    buildType(InitialBuild)

    subProject {
        id("FullBuild")
        name = "Full build"
        cellTypes.filterKeys { it.kind == Kind.FULL }.values.forEach { buildType(it) }
    }
    subProject {
        id("IntegrationTests")
        name = "Integration tests"
        cellTypes.filterKeys { it.kind == Kind.ITS }.values.forEach { buildType(it) }
    }
    subProject {
        id("Side")
        name = "Side workflows (paused)"
        buildType(SnapshotDeploy)
        sideWorkflows.forEach { buildType(it) }
    }
}
